#!/usr/bin/env python3
"""
Advanced Module 03: static validator for Nav2 behavior-tree XML (BehaviorTree.CPP v4).

Checks a tree against what is INSTALLED, not against a hand-written list:
  * Nav2 BT nodes + ports: TreeNodesModel generated by `generate_nav2_tree_nodes_xml`
    (nav2_behavior_tree, all default plugins)
  * DockRobot / UndockRobot ports: parsed from the installed opennav_docking_bt headers;
    their plugin libraries must exist and be listed in the bt_navigator plugin_lib_names YAML
  * BehaviorTree.CPP built-in control/decorator nodes (table below)
Also: BTCPP_format="4", main_tree_to_execute exists, battery thresholds are fractions 0..1.

  ros2 run amr_adv03 check_bt                                   # the module's tree
  ros2 run amr_adv03 check_bt my_tree.xml --plugins-yaml my_bt_navigator.yaml
"""

import argparse
import glob
import os
import re
import subprocess
import sys
import tempfile
import xml.etree.ElementTree as ET

import yaml
from ament_index_python.packages import get_package_prefix, get_package_share_directory

# BehaviorTree.CPP 4 built-ins used in Nav2 trees: name -> allowed ports
BTCPP_BUILTINS = {
    'Sequence': set(), 'SequenceWithMemory': set(), 'ReactiveSequence': set(),
    'Fallback': set(), 'ReactiveFallback': set(),
    'Parallel': {'success_count', 'failure_count'}, 'IfThenElse': set(), 'WhileDoElse': set(),
    'Inverter': set(), 'ForceSuccess': set(), 'ForceFailure': set(),
    'RetryUntilSuccessful': {'num_attempts'}, 'Repeat': {'num_cycles'},
    'KeepRunningUntilFailure': set(), 'Timeout': {'msec'}, 'Delay': {'delay_msec'},
    'RunOnce': {'then_skip'}, 'AlwaysSuccess': set(), 'AlwaysFailure': set(),
    'SubTree': {'ID', '_autoremap'},
}
GENERIC_ATTRS = {'name', 'ID', '_skipIf', '_successIf', '_failureIf', '_while', '_onSuccess',
                 '_onFailure', '_onHalted', '_post'}
DOCKING_NODES = {'DockRobot': ('dock_robot.hpp', 'opennav_dock_action_bt_node'),
                 'UndockRobot': ('undock_robot.hpp', 'opennav_undock_action_bt_node')}
BT_ACTION_BASIC_PORTS = {'server_name', 'server_timeout'}


def nav2_models():
    """{node ID: set(port names)} from nav2_behavior_tree's generator (all default plugins)."""
    exe = os.path.join(get_package_prefix('nav2_behavior_tree'), 'lib', 'nav2_behavior_tree',
                       'generate_nav2_tree_nodes_xml')
    with tempfile.TemporaryDirectory() as tmp:
        subprocess.run([exe], cwd=tmp, check=True, capture_output=True, timeout=60)
        root = ET.parse(os.path.join(tmp, 'nav2_tree_nodes.xml')).getroot()
    models = {}
    for node in root.find('TreeNodesModel'):
        models[node.get('ID')] = {p.get('name') for p in node}
    return models


def docking_models():
    """{DockRobot|UndockRobot: (ports, plugin library name)} from the installed headers."""
    prefix = get_package_prefix('opennav_docking_bt')
    models = {}
    for node_id, (header, lib) in DOCKING_NODES.items():
        path = os.path.join(prefix, 'include', 'opennav_docking_bt', header)
        with open(path) as f:
            text = f.read()
        ports = set(re.findall(r'Port<[^(]*>\(\s*"(\w+)"', text)) | BT_ACTION_BASIC_PORTS
        if not glob.glob(os.path.join(prefix, 'lib', f'lib{lib}.so')):
            raise FileNotFoundError(f'lib{lib}.so not installed')
        models[node_id] = (ports, lib)
    return models


def node_id(elem):
    if elem.tag in ('Action', 'Condition', 'Control', 'Decorator'):
        return elem.get('ID')
    return elem.tag


def check_tree(xml_path, plugin_libs, nav2=None, docking=None):
    """Return a list of error strings (empty = valid)."""
    nav2 = nav2_models() if nav2 is None else nav2
    docking = docking_models() if docking is None else docking
    errors = []
    root = ET.parse(xml_path).getroot()
    if root.tag != 'root' or root.get('BTCPP_format') != '4':
        errors.append('root must be <root BTCPP_format="4"> (Nav2 Jazzy uses BehaviorTree.CPP 4)')
    trees = {t.get('ID') for t in root.findall('BehaviorTree')}
    main = root.get('main_tree_to_execute')
    if main not in trees:
        errors.append(f'main_tree_to_execute="{main}" not among BehaviorTree IDs {sorted(trees)}')
    for tree in root.findall('BehaviorTree'):
        for elem in tree.iter():
            if elem is tree:
                continue
            nid = node_id(elem)
            attrs = set(elem.attrib) - GENERIC_ATTRS
            if nid in BTCPP_BUILTINS:
                allowed = BTCPP_BUILTINS[nid]
            elif nid in nav2:
                allowed = nav2[nid]
            elif nid in docking:
                allowed, lib = docking[nid]
                if lib not in plugin_libs:
                    errors.append(f'{nid}: add {lib} to bt_navigator plugin_lib_names')
            else:
                errors.append(f'unknown BT node "{nid}"')
                continue
            for a in sorted(attrs - allowed):
                errors.append(f'{nid}: unknown port "{a}" (known: {sorted(allowed)})')
            if nid == 'SubTree' and elem.get('ID') not in trees:
                errors.append(f'SubTree ID="{elem.get("ID")}" is not defined')
            if nid in ('IsBatteryLow',) and elem.get('is_voltage', 'false') == 'false':
                try:
                    value = float(elem.get('min_battery'))
                    if not 0.0 <= value <= 1.0:
                        errors.append(f'IsBatteryLow min_battery={value}: '
                                      'BatteryState.percentage is a fraction 0..1')
                except (TypeError, ValueError):
                    if not str(elem.get('min_battery', '')).startswith('{'):
                        errors.append('IsBatteryLow needs a numeric min_battery')
    return errors


def plugin_libs_from_yaml(path):
    with open(path) as f:
        data = yaml.safe_load(f)
    return set(data['bt_navigator']['ros__parameters'].get('plugin_lib_names', []))


def main(argv=None):
    share = get_package_share_directory('amr_adv03')
    parser = argparse.ArgumentParser(description='Validate a Nav2 behavior tree XML')
    parser.add_argument('xml', nargs='?',
                        default=os.path.join(share, 'behavior_trees', 'dock_and_charge_bt.xml'))
    parser.add_argument('--plugins-yaml',
                        default=os.path.join(share, 'config', 'bt_navigator_docking.yaml'))
    args_in = sys.argv[1:] if argv is None else argv
    if '--ros-args' in args_in:
        args_in = args_in[:args_in.index('--ros-args')]
    args = parser.parse_args(args_in)

    nav2 = nav2_models()
    docking = docking_models()
    print(f'installed models: {len(nav2)} Nav2 BT nodes, {len(docking)} docking BT nodes '
          f'({", ".join(sorted(docking))})')
    errors = check_tree(args.xml, plugin_libs_from_yaml(args.plugins_yaml), nav2, docking)
    root = ET.parse(args.xml).getroot()
    used = [node_id(e) for t in root.findall('BehaviorTree') for e in t.iter() if e is not t]
    print(f'{os.path.basename(args.xml)}: {len(used)} nodes: {", ".join(used)}')
    for e in errors:
        print('ERROR: ' + e)
    print('RESULT: ' + ('VALID' if not errors else f'{len(errors)} error(s)'))
    return 0 if not errors else 1


if __name__ == '__main__':
    sys.exit(main())
